async function sendWorkflowMessage(id,action){const input=document.querySelector(`[data-thread-message="${CSS.escape(id)}"]`),outcome=document.querySelector(`[data-thread-outcome="${CSS.escape(id)}"]`),text=input?.value??'';if(!input||pendingControls.has(id)||lastSnapshot?.daemon?.running===false)return;pendingControls.set(id,{kind:action,id:null});input.disabled=true;if(outcome)outcome.textContent='Sending to GitHub…';try{const response=await fetch('/api/control',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({kind:'message',target:id,text,action})}),data=await response.json();if(!response.ok)throw new Error(data.error);pendingControls.set(id,{kind:action,id:data.requestId});threadDrafts.set(id,'');input.value='';if(outcome)outcome.textContent='Message queued. Waiting for the daemon…';toast('Message queued.');await refresh();await loadWorkflowThread(id,true)}catch(error){pendingControls.delete(id);input.disabled=false;if(outcome)outcome.textContent=`Rejected: ${error.message}`;toast(error.message)}}
