  const sync=data.githubSync;$('#workflow-sync').textContent=sync?sync.state==='syncing'?'Syncing GitHub…':sync.state==='failed'?'GitHub sync delayed':`GitHub synced ${relative(sync.at)}`:'';
  renderIssueList(data);
