  $('#usage-metrics').innerHTML=data.usage?.length?data.usage.map(item=>{const issue=item.url?githubLink(item.url,`#${escapeHtml(item.issue)} ${escapeHtml(item.title)}`):`<strong>${escapeHtml(item.title||item.workItemId)}</strong>`;const partial=item.unreportedTokenRuns?`<small>${item.unreportedTokenRuns} run${item.unreportedTokenRuns===1?'':'s'} without reported usage</small>`:'';const rows=item.stages.map(stage=>`<tr><td data-label="Workflow stage"><span class="state ${stateClass(stage.state)}"><i></i>${escapeHtml(statusName(stage.state))}</span></td><td data-label="Agent">${escapeHtml(roleName(stage.role))}</td><td data-label="Runs">${escapeHtml(stage.runs)}</td><td data-label="Time">${escapeHtml(duration(stage.durationMs))}</td><td data-label="Tokens">${escapeHtml(tokens(stage.totalTokens))}${stage.unreportedTokenRuns?` <small>+ ${stage.unreportedTokenRuns} unavailable</small>`:''}</td></tr>`).join('');return `<details class="usage-card" data-usage-item="${escapeHtml(item.workItemId)}" ${expandedUsageItems.has(item.workItemId)?'open':''}><summary class="usage-head"><div class="usage-issue">${issue}${partial}</div><dl><div><dt>Runs</dt><dd>${escapeHtml(item.runs)}</dd></div><div><dt>Agent time</dt><dd>${escapeHtml(duration(item.durationMs))}</dd></div><div><dt>Reported tokens</dt><dd>${escapeHtml(tokens(item.totalTokens))}</dd></div></dl><span class="usage-toggle"><span class="usage-show">Show breakdown</span><span class="usage-hide">Hide breakdown</span><i aria-hidden="true">⌄</i></span></summary><div class="usage-table-wrap"><table><thead><tr><th>Workflow stage</th><th>Agent</th><th>Runs</th><th>Time</th><th>Tokens</th></tr></thead><tbody>${rows}</tbody></table></div></details>`}).join(''):'<p class="empty">No agent usage has been recorded yet.</p>';
