  const local=data.items.map(item=>{const pending=pendingControls.get(item.id)||item.control?.pending&&item.control;const daemonStopped=data.daemon?.running===false,actions=((item.actions||[]).map(action=>`<button ${pending||daemonStopped?'disabled':''} class="${action==='cancel'?'danger':''}" onclick="factoryControl('${escapeHtml(action)}','${escapeHtml(item.id)}')">${escapeHtml({pause:'Pause',resume:'Resume',retry:'Retry',cancel:'Cancel'}[action])}</button>`).join(''))+(item.status==='FAILED'?`<button type="button" onclick="diagnoseIssue('${escapeHtml(item.id)}')">Technical details</button>`:'');const label=`${statusName(item.stage)} · ${['RUNNING','QUEUED'].includes(item.status)&&item.activity?item.activity.label:statusName(item.status)}`,continuity=item.continuity?`<p>Continued from ${escapeHtml(item.continuity.instance)} at revision ${escapeHtml(item.continuity.revision)}</p>`:'';return `<article class="item local-item"><div class="work-item-heading">${githubLink(item.url,`#${escapeHtml(item.issue)} ${escapeHtml(item.title||item.id)}`)}<p>Attempt ${escapeHtml(item.attempt)} · ${relative(item.updatedAt)} <span class="work-item-id" title="${escapeHtml(item.id)}">· ${escapeHtml(item.id.slice(0,8))}</span></p>${continuity}</div><span class="state ${stateClass(item.status)}"><i></i>${escapeHtml(label)}</span><div class="actions work-item-actions">${actions}</div>${pending?`<p class="work-control-pending" role="status">${escapeHtml(pending.kind)} requested · waiting for the daemon</p>`:item.control?.error?`<p class="work-control-pending" role="alert">Request failed: ${escapeHtml(item.control.error)}</p>`:''}${item.nextStep?`<div class="work-next-step"><div class="next-step-copy"><strong>${escapeHtml(item.nextStep.title)}</strong>${item.nextStep.needsAttention?'<p>Pull request link unavailable. Check the issue before continuing.</p>':''}</div><a class="next-step-link" href="${escapeHtml(item.nextStep.url||item.url)}" target="_blank" rel="noreferrer">${escapeHtml(item.nextStep.url?'Review pull request':'Open issue')} <span aria-hidden="true">↗</span></a>${item.nextStep.command?`<details class="next-step-help" data-work-details="${escapeHtml(item.id)}-next" ${expandedWorkDetails.has(item.id+'-next')?'open':''}><summary>${item.nextStep.url?'How to request changes':'How to respond'}</summary><p>${escapeHtml(item.nextStep.description)}</p><p>${escapeHtml(item.nextStep.commandHelp)}</p><code>${escapeHtml(item.nextStep.command)}</code><a href="${escapeHtml(item.url)}" target="_blank" rel="noreferrer">Open issue ↗</a></details>`:''}</div>`:''}${workDetails(item,expandedWorkDetails)}<details class="workflow-thread-panel" data-work-details="${escapeHtml(item.id)}-thread" data-thread-panel="${escapeHtml(item.id)}" ${expandedWorkDetails.has(item.id+'-thread')?'open':''}><summary>Workflow conversation</summary><div data-work-thread-body="${escapeHtml(item.id)}"><p class="muted">Open to load the conversation.</p></div></details></article>`}).join('');
  const sameRepository=Boolean(remoteIssueData?.repository)&&remoteIssueData.repository.toLowerCase()===data.repository?.toLowerCase();
