function sameRepositoryIssueData(data){return Boolean(remoteIssueData?.repository)&&remoteIssueData.repository.toLowerCase()===data.repository?.toLowerCase()?remoteIssueData:null}
function renderRemoteIssueStatus(data){const sameRepository=Boolean(sameRepositoryIssueData(data));$('#remote-issues-updated').textContent=remoteIssueError?`GitHub refresh unavailable: ${remoteIssueError}${sameRepository&&remoteIssueCheckedAt?` · Last checked ${relative(remoteIssueCheckedAt)}`:''}`:sameRepository&&remoteIssueCheckedAt?`GitHub view · checked ${relative(remoteIssueCheckedAt)}. Task controls and KPIs use this installation’s live state.`:'GitHub view · awaiting refresh'}
async function refresh(){try{const response=await pollingFetch(`/api/snapshot?lines=${encodeURIComponent($('#daemon-log-lines').value)}`,{cache:'no-store',signal:AbortSignal.timeout(15000)});if(!response.ok)throw new Error('Dashboard API unavailable');render(await response.json())}catch(error){if(pollingInterrupted(error))return;toast(error.message)}}
function renderRemoteIssues(data){remoteIssueData=data;remoteIssueCheckedAt=new Date().toISOString();remoteIssueError='';if(lastSnapshot){renderIssueList(lastSnapshot);applyQueueAvailability()}}
let remoteIssuesLoading=false;
async function loadRemoteIssues(){if(remoteIssuesLoading)return;remoteIssuesLoading=true;try{const response=await pollingFetch('/api/issues/remote'),data=await response.json();if(!response.ok)throw new Error(data.error);renderRemoteIssues(data)}catch(error){if(pollingInterrupted(error))return;remoteIssueError=error.message;if(lastSnapshot)renderIssueList(lastSnapshot)}finally{remoteIssuesLoading=false}}
async function refreshIssueList(){await factoryControl('refresh-list');await loadRemoteIssues()}window.refreshIssueList=refreshIssueList;
async function workHere(issue){await factoryControl('claim-issue',String(issue));await loadRemoteIssues()}window.workHere=workHere;
async function continueHere(issue){await factoryControl('continue-issue',String(issue));await loadRemoteIssues()}window.continueHere=continueHere;

function settingsProgress(message,state='busy'){const progress=$('#settings-progress');progress.hidden=false;progress.textContent=message;progress.dataset.state=state;$('#settings-form').setAttribute('aria-busy',String(state==='busy'));$('#settings-save').textContent=state==='busy'?'Applying…':'Save and apply';}
function applySettingsLock(){document.querySelectorAll('[data-setting],[data-provider-choice],[data-clear-secret],#settings-actions button[type="submit"]').forEach(control=>control.disabled=settingsBusy);document.querySelectorAll('[data-slack-connect]').forEach(control=>control.disabled=slackBusy)}
function credentialCards(data){return data.credentials.map(item=>{const connected=item.status==='connected',connecting=item.status==='connecting',failed=item.status==='failed';const state=connected?'Connected':connecting?'Connecting…':failed?'Login failed':'Not connected';const stateClassName=connected?'state-merged':connecting?'state-paused':failed?'state-failed':'state-cancelled';const action=connected?'Reconnect':'Connect';return `<article class="credential-card"><div class="credential-copy"><div><h4>${brandLabel(item.id,item.label,{accessibleLabel:item.label,title:item.label})}</h4><span class="state ${stateClassName}"><i></i>${state}</span></div><p>${escapeHtml(item.description)}</p>${item.account?`<strong class="credential-account">${escapeHtml(item.account)}</strong>`:''}${failed?`<small>Open the credential log for details, then retry.</small>`:''}</div><button type="button" onclick="connectCredential('${escapeHtml(item.id)}')" ${credentialBusy||connecting||!item.installed?'disabled':''}>${!item.installed?'CLI unavailable':connecting?'Waiting for browser…':action}</button></article>`}).join('')}
function slackWebhookCard(){const state=slackData.configured?'Connected':'Not connected',stateClassName=slackData.configured?'state-merged':'state-cancelled';return `<article class="credential-card slack-webhook-card"><div class="credential-copy"><div><h4>${brandLabel('slack','Slack webhook')}</h4><span class="state ${stateClassName}"><i></i>${state}</span></div><p>Optional workflow notifications sent through a Slack Incoming Webhook.</p>${slackData.configured?`<strong class="credential-account">${slackData.pending} pending · ${slackData.failed} failed · ${slackData.sent} sent</strong>`:''}</div><div class="credential-actions"><button type="button" data-slack-connect onclick="openSlackSettings()" ${slackBusy?'disabled':''}>${slackData.configured?'Manage':'Connect'}</button></div></article>`}
function renderCredentials(data){credentialsData=data;const list=$('#credentials-list');if(list)list.innerHTML=credentialCards(data);const log=$('#credentials-log');if(log)log.textContent=data.log||'data/service-logs/credentials.log'}
async function loadCredentials(){try{const wasConnected=credentialsData.credentials.find(item=>item.id==='github')?.status==='connected';const response=await pollingFetch('/api/credentials',{cache:'no-store',signal:AbortSignal.timeout(10000)});const data=await response.json();if(!response.ok)throw new Error(data.error);renderCredentials(data);if(settingsLoaded&&!wasConnected&&data.credentials.find(item=>item.id==='github')?.status==='connected')await loadSettings()}catch(error){if(pollingInterrupted(error))return;if($('#credentials-list'))$('#credentials-list').innerHTML=`<p class="empty">${escapeHtml(error.message)}</p>`}}
async function connectCredential(provider){if(credentialBusy)return;credentialBusy=true;renderCredentials(credentialsData);try{const response=await fetch('/api/credentials/connect',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({provider})});const data=await response.json();if(!response.ok)throw new Error(data.error);toast(data.message);await loadCredentials()}catch(error){toast(error.message)}finally{credentialBusy=false;await loadCredentials()}}
window.connectCredential=connectCredential;
function renderSlack(data){const card=$('#slack-connection');slackData=data;if(card)card.innerHTML=slackWebhookCard();applySettingsLock()}
async function loadSlack(){try{const response=await pollingFetch('/api/slack',{cache:'no-store',signal:AbortSignal.timeout(10000)});const data=await response.json();if(!response.ok)throw new Error(data.error);renderSlack(data)}catch(error){if(pollingInterrupted(error))return;if($('#slack-connection'))$('#slack-connection').innerHTML=`<p class="empty">${escapeHtml(error.message)}</p>`}}
function openSlackSettings(){const dialog=$('#slack-dialog'),input=$('#slack-webhook-url');$('#slack-dialog-error').textContent='';$('#slack-dialog-status').textContent=slackData.configured?`${slackData.pending} pending · ${slackData.failed} failed · ${slackData.sent} sent`:'';$('#slack-dialog-last-error').textContent=slackData.lastError?`Last delivery error: ${slackData.lastError}`:'';input.value='';input.placeholder=slackData.configured?'Paste a replacement Incoming Webhook URL':'https://hooks.slack.com/services/…';$('#slack-test').hidden=!slackData.configured;dialog.showModal();input.focus()}
function closeSlackSettings(){$('#slack-dialog').close()}
async function saveSlackSettings(event){event.preventDefault();if(slackBusy)return;const input=$('#slack-webhook-url'),error=$('#slack-dialog-error'),webhook=input.value.trim();if(!webhook){error.textContent='Enter an Incoming Webhook URL.';input.focus();return}slackBusy=true;applySettingsLock();$('#slack-save').disabled=true;error.textContent='';try{const response=await fetch('/api/slack',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({webhook,clear:false})}),data=await response.json();if(!response.ok)throw new Error(data.error);renderSlack(data);closeSlackSettings();toast(data.message)}catch(problem){error.textContent=problem.message}finally{slackBusy=false;$('#slack-save').disabled=false;applySettingsLock()}}
