function repositoryCard(){return `<section class="role-routing-card repository-maintenance"><div><p class="eyebrow">REPOSITORY MAINTENANCE</p><h4>Local and remote recovery</h4><p>Check the repository, sync changes or recover the local checkout.</p></div><div id="repository-check" class="repository-result" role="status"><p>Check the repository to see its status and recommended next steps.</p></div><button id="repository-diagnose" type="button" hidden onclick="diagnoseOperationFailure('repository-diagnose')">Diagnose failure</button><div class="repository-actions"><button type="button" onclick="repositoryAction('check')">Check repository</button><button type="button" onclick="repositoryAction('sync')">Sync from remote</button><button type="button" onclick="repositoryAction('restore')">Restore from remote</button></div><div class="repository-danger"><div><strong>Remove local repository</strong><p>Deletes the checkout and Factory worktrees. Tasks will be paused. GitHub is unchanged. Back up any files you need first.</p></div><button type="button" class="danger" onclick="repositoryAction('clear')">Clear local copy</button></div><div class="repository-publish"><label for="repository-work-item"><strong>Publish a work item branch</strong><input id="repository-work-item" placeholder="Work item ID"></label><button type="button" onclick="repositoryAction('publish')">Publish branch</button></div></section>`}
let repositoryBusy=false;
function renderRepositoryResult(data,action){const messages={sync:'Repository synchronized.',restore:'Local repository restored.',clear:'Local copy removed. Restore it from GitHub before resuming tasks.',publish:'Work item branch published to GitHub.'};if(action==='publish'||action==='clear'){$('#repository-check').innerHTML=`<strong>${escapeHtml(messages[action])}</strong>${data.branch?`<p>Branch: ${escapeHtml(data.branch)}</p>`:''}`;return}const title=!data.exists||data.empty?'Local repository is missing':!data.git?'This folder is not a Git repository':!data.originMatches?'Repository does not match your configuration':data.inconsistencies?.length||data.dirty?.length||data.untracked?.length||data.unpushed?'Repository needs attention':'Repository check complete';const facts=[['Location',data.root],['Branch',data.branch||data.defaultBranch],['Changed files',data.dirty?.length??0],['New files',data.untracked?.length??0],['Unpublished commits',data.unpushed??0],['Task worktrees',Math.max(0,(data.worktrees?.length??1)-1)]];$('#repository-check').innerHTML=`<strong>${escapeHtml(messages[action]||title)}</strong><p>${escapeHtml(data.recommendation||'Review the configured repository path.')}</p><dl>${facts.map(([label,value])=>`<div><dt>${escapeHtml(label)}</dt><dd>${escapeHtml(value)}</dd></div>`).join('')}</dl>${data.inconsistencies?.length?`<ul>${data.inconsistencies.map(message=>`<li>${escapeHtml(message)}</li>`).join('')}</ul>`:''}<p class="muted">Commit counts use the last fetched remote state. Sync checks GitHub again before updating files.</p>`;}
