function renderSetupGuide(readiness){const guide=$('#setup-guide'),list=$('#setup-requirements');if(!guide||!list)return;const missing=readiness?.missing||[];const product=item=>item.id?.includes('github')?'github':item.id?.includes('claude')?'claude':item.id?.includes('codex')?'codex':item.id?.includes('cursor')?'cursor':item.id?.includes('git')?'git':null;guide.hidden=Boolean(readiness?.ready||!missing.length);list.innerHTML=missing.map(item=>{const brand=product(item),label=brand==='codex'?item.label.replace(/Codex\s*(or\s*)?/i,''):item.label;return `<li>${brand?brandIcon(brand):''}<span>${escapeHtml(label)}</span></li>`}).join('')}
