  $('#settings-summary').textContent=`${available.length} categories · ${data.fields.length} variables`;daemonRunning=data.daemonRunning;renderSetupGuide(data.readiness);applySettingsLock();$('#settings-change-status').textContent=setupMode&&!data.daemonRunning?'A valid first-time save starts the daemon automatically.':'Values are validated before affected running services restart automatically.';settingsLoaded=true;
