function settingsLoadFailure(message,reconnecting=false){$('#settings-status').textContent=message;if(settingsLoaded)return;$('#settings-summary').textContent=reconnecting?'Reconnecting…':'Configuration unavailable';$('#settings-navigation').innerHTML='';$('#settings-groups').innerHTML=`<div class="settings-load-state ${reconnecting?'':'error'}" role="${reconnecting?'status':'alert'}"><strong>${reconnecting?'Reconnecting to the dashboard':'Configuration could not be loaded'}</strong><p>${escapeHtml(message)}</p><button type="button" onclick="loadSettings()">Retry</button></div>`;$('#settings-save').disabled=true}
